    const left = Math.max(0, Math.floor(Math.min(...corners.map(p => p.x))) - 1);
    const top = Math.max(0, Math.floor(Math.min(...corners.map(p => p.y))) - 1);
    const right = Math.min(surface?.width ?? Infinity, Math.ceil(Math.max(...corners.map(p => p.x))) + 1);
    const bottom = Math.min(surface?.height ?? Infinity, Math.ceil(Math.max(...corners.map(p => p.y))) + 1);
    if (right <= left || bottom <= top) return;
    const width = right - left, height = bottom - top;
    const key = JSON.stringify([part.assetKey, part.sourceSize, part.clipPolygon, part.clipPolygons, part.clipInverted,
