import hashlib
import json
import copy
from pathlib import Path
from PIL import Image

ROOT = Path(__file__).resolve().parents[1]
ART = ROOT.parent / "月下温泉-补全修订"


def write(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n")


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def point(x, y):
    return {"x": round(x, 6), "y": round(y, 6)}


def size(w, h):
    return {"width": round(w, 6), "height": round(h, 6)}


def union(rects):
    x0 = min(r["x"] for r in rects)
    y0 = min(r["y"] for r in rects)
    x1 = max(r["x"] + r["width"] for r in rects)
    y1 = max(r["y"] + r["height"] for r in rects)
    return dict(x=x0, y=y0, width=x1-x0, height=y1-y0)


def alpha_rle(path):
    im = Image.open(path).convert("RGBA")
    raw = im.getchannel("A").tobytes()
    runs, start = [], None
    for i, value in enumerate(raw):
        if value >= 19 and start is None:
            start = i
        elif value < 19 and start is not None:
            runs.extend((start, i-start))
            start = None
    if start is not None:
        runs.extend((start, len(raw)-start))
    return dict(width=im.width, height=im.height, runs=runs, pngSHA256=sha(path))


